/* hub-nav.v1 — behavior for the corner hub switcher (markup is generated by hubgen).
   Mouse: hover opens; clicking the arrow goes up a level.
   Touch: first tap opens; a second tap on the arrow goes up a level.
   Keyboard: Tab opens via :focus-within; Escape closes.

   Hubs with their own internal levels call window.hubNav.setUp(href, label) on every route
   change so the arrow steps back one level inside the hub, and window.hubNav.reset() at the
   hub's top level, where the arrow goes back to the Classroom Hub. */
(function () {
  var nav = document.querySelector(".hub-nav");
  if (!nav) return;
  var up = nav.querySelector(".hub-nav__up");
  var upRow = nav.querySelector(".hub-nav__link--up");
  var upLabel = nav.querySelector(".hub-nav__uplabel");
  var upSr = nav.querySelector(".hub-nav__sr");
  var rootRow = nav.querySelector('[data-hub-nav="root"]');
  var here = nav.querySelector("[data-hub-nav-current]");
  var def = { href: up.getAttribute("href"), label: up.dataset.label };
  var lastPointer = "mouse";

  function setOpen(on) {
    nav.classList.toggle("is-open", on);
    nav.classList.toggle("is-closed", !on);
    up.setAttribute("aria-expanded", on ? "true" : "false");
  }
  function apply(href, label) {
    var atTop = href === def.href;
    up.setAttribute("href", href);
    up.title = "Back to " + label;
    if (upSr) upSr.textContent = "Back to " + label;
    upRow.setAttribute("href", href);
    upLabel.textContent = label;
    // At the hub's top level "up" is the Classroom Hub, so its own row would repeat it.
    if (rootRow) rootRow.hidden = atTop;
    if (here) {
      if (atTop) here.setAttribute("aria-current", "page");
      else here.removeAttribute("aria-current");
    }
  }

  window.hubNav = {
    setUp: function (href, label) { apply(href, label); },
    reset: function () { apply(def.href, def.label); }
  };
  // This script is deferred, so a hub that routes during parse re-syncs once the API exists.
  document.dispatchEvent(new Event("hubnav:ready"));

  // Pointer events, not mouse events: touch browsers fire compatibility mouseleave right after a tap.
  nav.addEventListener("pointerenter", function (e) { if (e.pointerType === "mouse") nav.classList.remove("is-closed"); });
  nav.addEventListener("pointerleave", function (e) { if (e.pointerType === "mouse") setOpen(false), nav.classList.remove("is-closed"); });
  up.addEventListener("pointerdown", function (e) { lastPointer = e.pointerType || "mouse"; });
  up.addEventListener("click", function (e) {
    if (lastPointer !== "mouse" && !nav.classList.contains("is-open")) { e.preventDefault(); setOpen(true); return; }
    nav.classList.remove("is-open");
    nav.classList.add("is-closed");
    up.blur();
  });
  nav.addEventListener("click", function (e) {
    var a = e.target.closest && e.target.closest(".hub-nav__link");
    if (!a) return;
    if (a.getAttribute("aria-current") === "page") e.preventDefault();
    setOpen(false);
    a.blur();
  });
  document.addEventListener("pointerdown", function (e) {
    if (!nav.contains(e.target) && nav.classList.contains("is-open")) setOpen(false);
  });
  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape" && (nav.matches(":focus-within") || nav.classList.contains("is-open"))) {
      setOpen(false);
      if (document.activeElement && nav.contains(document.activeElement)) document.activeElement.blur();
    }
  });
})();
